export function getPlacesForState(stateFipsOrName: string): SePlace[] {
  const key = String(stateFipsOrName || '').trim();
  if (SE_PLACES_BY_STATE_FIPS[key]) return SE_PLACES_BY_STATE_FIPS[key];
  const state = SE_PLACE_STATES.find(
    (s) => s.name.toLowerCase() === key.toLowerCase() || s.abbr.toLowerCase() === key.toLowerCase() || s.fips === key.padStart(2, '0'),
  );
  return state ? SE_PLACES_BY_STATE_FIPS[state.fips] || [] : [];
}

export function resolveSePlace(stateNameOrAbbrOrFips: string, placeName: string): { stateFips: string; placeFips: string; stateName: string; placeName: string } | null {
  const sKey = String(stateNameOrAbbrOrFips || '').trim();
  const pKey = String(placeName || '').trim().toLowerCase();
  const state = SE_PLACE_STATES.find(
    (s) =>
      s.name.toLowerCase() === sKey.toLowerCase() ||
      s.abbr.toLowerCase() === sKey.toLowerCase() ||
      s.fips === sKey.padStart(2, '0'),
  );
  if (!state) return null;
  const places = SE_PLACES_BY_STATE_FIPS[state.fips] || [];
  const place =
    places.find((p) => p.name.toLowerCase() === pKey) ||
    places.find((p) => p.name.toLowerCase().replace(/ (city|town|village|cdp)$/i, '') === pKey.replace(/ (city|town|village|cdp)$/i, ''));
  if (!place) return null;
  return { stateFips: state.fips, placeFips: place.placeFips, stateName: state.name, placeName: place.name };
}

export function isValidSePlace(stateFips: string, placeFips: string): boolean {
  const sf = String(stateFips || '').trim().padStart(2, '0');
  const pf = String(placeFips || '').trim().padStart(5, '0');
  const places = SE_PLACES_BY_STATE_FIPS[sf];
  if (!places) return false;
  return places.some((p) => p.placeFips === pf);
}
